BEGIN;
-- a spare position, registered the way topology would register it
SELECT farm.register_slot('h01','3-1.9','3-1',9,
         'StarTech ST7300USBM 7-port',7,true,'R1-U04-H1-P9') AS new_slot_id;
-- an unbranded, un-fingerprinted phone carrying the clone serial turns up there
