         '0123456789ABCDEF', 'default',
         '{"manufacturer":"Google","model":"Pixel 7"}'::jsonb);
SELECT count(*) AS rows_with_clone_serial
  FROM farm.devices WHERE adb_serial = '0123456789ABCDEF';
ROLLBACK;

BEGIN;
SELECT * FROM farm.resolve_device('h01','3-1.1', NULL, NULL,
         '0123456789ABCDEF', 'default', '{}'::jsonb);
