// Run as the real internal/enroll.HardwareFingerprint via
//   go test -overlay <scratch>/overlay.json -run TestDocsDump ./internal/enroll/
// which maps a scratchpad test file into the package without writing to the tree.
// sha256 input, length-prefixed:
//   20:device-farmer/hwfp/1 12:manufacturer 6:Google 5:model 7:Pixel 7
//   6:device 7:panther 8:hardware 7:panther 6:serial 16:0123456789ABCDEF

BEGIN;
-- a cheap 4-port hub with NO per-port VBUS switching
SELECT farm.register_slot('h01','5-4.3','5-4',3,'Cheap 4-port hub',4,false,'R1-U04-H9-P3') AS slot_id;

SELECT c.root_bus, hb.usb_path AS hub, hb.port_count, hb.vbus_switchable,
       pd.kind AS power_kind, pd.control, pd.control_addr,
       s.usb_path, s.adb_devpath, s.topo_path::text, s.rack_slot
  FROM farm.slots s
  JOIN farm.hubs hb          ON hb.id = s.hub_id
  JOIN farm.controllers c    ON c.id  = hb.controller_id
  JOIN farm.power_domains pd ON pd.id = s.power_domain_id
 WHERE s.host_id='h01' AND s.usb_path='5-4.3';
ROLLBACK;

BEGIN;
SELECT p AS port,
       farm.register_slot('h01','5-4.'||p,'5-4',p,'Cheap 4-port hub',4,false,'R1-U04-H9-P'||p)
  FROM generate_series(1,4) p;

SELECT s.usb_path, s.power_domain_id, pd.kind, pd.control,
       count(*) OVER (PARTITION BY s.power_domain_id) AS slots_sharing_this_domain
  FROM farm.slots s JOIN farm.power_domains pd ON pd.id = s.power_domain_id
 WHERE s.host_id='h01' AND s.usb_path LIKE '5-4.%' ORDER BY s.usb_path;
ROLLBACK;

SELECT s.rack_slot, s.usb_path, hb.usb_path AS hub
  FROM farm.slots s JOIN farm.hubs hb ON hb.id = s.hub_id
 WHERE s.host_id = 'h01' AND s.port_number = 1 ORDER BY hb.usb_path;
